import { AdminEmpty, AdminSection } from '@/components/admin/shared';
import { useChat } from '@/contexts/ChatContext';

export const ChatManager = () => {
  const { threads } = useChat();

  return (
    <AdminSection
      title="المحادثات"
      description="محادثات العملاء مع المعارض والمصممين داخل التطبيق."
    >
      {threads.length === 0 ? (
        <AdminEmpty message="لا توجد محادثات بعد." />
      ) : (
        <div className="space-y-3">
          {threads.map((thread) => (
            <div key={thread.threadId} className="rounded-2xl border border-border bg-card p-4">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <div className="min-w-0">
                  <p className="truncate text-sm font-medium">{thread.name}</p>
                  <p className="mt-0.5 text-[11px] text-wood">
                    {thread.type === 'designer' ? 'مصمم / نجار' : 'معرض'} · {thread.phone}
                  </p>
                </div>
                <span className="rounded-full bg-secondary px-2.5 py-1 text-[11px] text-muted-foreground">
                  {thread.messages.length} رسالة
                </span>
              </div>
              {thread.messages.length > 0 && (
                <ul className="mt-3 space-y-1.5 border-t border-border pt-3">
