import { useRef, useState } from 'react';
import { Download, Upload } from 'lucide-react';
import { toast } from 'sonner';
import { AdminSection } from '@/components/admin/shared';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { useCatalog } from '@/contexts/CatalogContext';

export const DataTools = () => {
  const { exportData, importData } = useCatalog();
  const [raw, setRaw] = useState('');
  const [busy, setBusy] = useState(false);
  const fileRef = useRef<HTMLInputElement>(null);

  const download = () => {
    const payload = exportData();
    const blob = new Blob([payload], { type: 'application/json;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `ewan-backup-${new Date().toISOString().slice(0, 10)}.json`;
    link.click();
    URL.revokeObjectURL(url);
    toast.success('تم تصدير نسخة احتياطية');
  };

  const runImport = async (content: string) => {
    if (!content.trim()) {
      toast.error('الصق محتوى JSON أو اختر ملفاً');
      return;
    }
    setBusy(true);
    try {
      await importData(content);
      toast.success('تم استيراد البيانات بنجاح');
      setRaw('');
    } catch (cause) {
      toast.error('تعذّر الاستيراد', {
        description: cause instanceof Error ? cause.message : 'تحقق من صيغة الملف.',
      });
    } finally {
      setBusy(false);
    }
  };

  return (
    <AdminSection
      title="تصدير / استيراد البيانات (JSON)"
      description="احفظ نسخة كاملة من بيانات المنصة، أو استعد نسخة سابقة — لا تضيع أي بيانات أدخلتها يدوياً."
    >
      <div className="grid gap-5 md:grid-cols-2">
        <div className="rounded-2xl border border-border bg-card p-6">
          <h3 className="text-sm font-medium">تصدير نسخة احتياطية</h3>
          <p className="mt-2 text-pretty text-sm leading-relaxed text-muted-foreground">
            يشمل التصدير المنتجات والمعارض والمصممين والشركاء والآراء والأسئلة والطلبات.
          </p>
          <Button onClick={download} className="mt-5 h-11 w-full rounded-full bg-primary text-primary-foreground hover:bg-primary/90">
            <Download className="ml-2 h-4 w-4" strokeWidth={1.8} />
            تنزيل ملف JSON
          </Button>
        </div>

        <div className="rounded-2xl border border-border bg-card p-6">
          <h3 className="text-sm font-medium">استيراد بيانات</h3>
          <p className="mt-2 text-pretty text-sm leading-relaxed text-muted-foreground">
            اختر ملف JSON أو الصق محتواه. سيتم دمج البيانات مع الحالية.
          </p>
          <input
            ref={fileRef}
            type="file"
            accept="application/json"
            className="hidden"
            onChange={(event) => {
              const file = event.target.files?.[0];
              if (!file) return;
              const reader = new FileReader();
              reader.onload = () => void runImport(String(reader.result ?? ''));
              reader.readAsText(file);
              event.target.value = '';
            }}
          />
          <Button
            variant="outline"
            onClick={() => fileRef.current?.click()}
            className="mt-5 h-11 w-full rounded-full border-border"
          >
            <Upload className="ml-2 h-4 w-4" strokeWidth={1.8} />
            اختيار ملف
          </Button>
        </div>

        <div className="md:col-span-2">
          <Textarea
            value={raw}
            onChange={(event) => setRaw(event.target.value)}
            rows={6}
            dir="ltr"
            placeholder='{"products": [...], "stores": [...]}'
            className="rounded-2xl border-border px-3 font-mono text-xs"
          />
          <Button
            onClick={() => void runImport(raw)}
            disabled={busy}
            className="mt-3 h-11 rounded-full bg-primary px-6 text-primary-foreground hover:bg-primary/90"
          >
            {busy ? 'جارٍ الاستيراد…' : 'استيراد من النص'}
          </Button>
        </div>
      </div>
    </AdminSection>
  );
};

