import { useEffect, useRef, useState } from 'react';
import { MessageCircle, Send } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Sheet, SheetContent, SheetTitle } from '@/components/ui/sheet';
import { useChat } from '@/contexts/ChatContext';
import { buildChatMessage, waLink } from '@/lib/order';
import { cn } from '@/lib/utils';

export const ChatDrawer = () => {
  const { activeThread, closeChat, sendMessage } = useChat();
  const [draft, setDraft] = useState('');
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (listRef.current) {
      listRef.current.scrollTop = listRef.current.scrollHeight;
    }
  }, [activeThread?.messages.length]);

  const handleSend = (event: React.FormEvent) => {
    event.preventDefault();
    if (!draft.trim()) return;
    sendMessage(draft);
    setDraft('');
  };

  return (
    <Sheet open={Boolean(activeThread)} onOpenChange={(open) => !open && closeChat()}>
      <SheetContent
        side="left"
        className="flex w-full max-w-md flex-col gap-0 border-r border-border bg-background p-0"
      >
        <SheetTitle className="sr-only">محادثة داخل التطبيق</SheetTitle>

        <div className="border-b border-border px-5 py-4">
          <p className="text-[11px] text-wood">محادثة داخل إيوان</p>
          <p className="mt-1 truncate text-base font-medium">{activeThread?.name ?? 'محادثة'}</p>
          <p className="mt-0.5 text-[11px] text-muted-foreground">
            رسائلك تُحفظ وتظهر لفريق {activeThread?.type === 'designer' ? 'المصمم' : 'المعرض'} ولوحة التحكم.
          </p>
        </div>

        <div ref={listRef} className="flex-1 overflow-y-auto bg-secondary/40 px-4 py-4">
          {activeThread && activeThread.messages.length === 0 ? (
            <div className="mx-auto mt-10 max-w-xs rounded-2xl border border-border bg-background p-5 text-center">
              <MessageCircle className="mx-auto h-6 w-6 text-wood" strokeWidth={1.4} />
              <p className="mt-3 text-sm font-medium">ابدأ المحادثة</p>
              <p className="mt-1 text-pretty text-xs leading-relaxed text-muted-foreground">
                اكتب سؤالك عن القطعة أو موعد التركيب، وسيصلك الرد من {activeThread.name}.
              </p>
            </div>
          ) : (
            <ul className="space-y-3">
              {activeThread?.messages.map((message) => (
                <li
                  key={message.id}
                  className={cn('flex', message.from === 'customer' ? 'justify-start' : 'justify-end')}
                >
                  <div
                    className={cn(
                      'max-w-[80%] rounded-2xl px-4 py-2.5 text-sm leading-relaxed',
                      message.from === 'customer'
                        ? 'bg-primary text-primary-foreground'
                        : 'border border-border bg-background text-foreground',
                    )}
                  >
                    {message.text}
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>

        <div className="border-t border-border px-4 py-3">
          <form onSubmit={handleSend} className="flex items-center gap-2">
            <Input
              value={draft}
              onChange={(event) => setDraft(event.target.value)}
              placeholder="اكتب رسالتك…"
              className="h-11 rounded-full"
            />
            <Button
              type="submit"
              aria-label="إرسال"
              className="h-11 w-11 shrink-0 rounded-full bg-primary p-0 text-primary-foreground hover:bg-primary/90"
            >
              <Send className="h-4 w-4" strokeWidth={1.8} />
            </Button>
          </form>

          {activeThread && (
            <Button
              asChild
              variant="outline"
              className="mt-2 h-11 w-full rounded-full border-wood/40 text-wood hover:bg-sand/40"
            >
              <a
                href={waLink(activeThread.phone, buildChatMessage(activeThread.name))}
                target="_blank"
                rel="noreferrer"
              >
                متابعة المحادثة عبر واتساب
              </a>
            </Button>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
};

