import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from 'react';

export interface ChatMessage {
  id: string;
  from: 'customer' | 'provider';
  text: string;
  at: string;
}

export interface ChatTarget {
  type: 'store' | 'designer';
  id: string;
  name: string;
  phone: string;
}

export interface ChatThread extends ChatTarget {
  threadId: string;
  messages: ChatMessage[];
  updatedAt: string;
}

interface ChatContextValue {
  threads: ChatThread[];
  activeThread: ChatThread | null;
  openChat: (target: ChatTarget) => void;
  closeChat: () => void;
  sendMessage: (text: string) => void;
  totalMessages: number;
}

const ChatContext = createContext<ChatContextValue | null>(null);

const STORAGE_KEY = 'ewan_v4_chats';

const isMessage = (value: unknown): value is ChatMessage => {
  if (!value || typeof value !== 'object') return false;
  const record = value as Record<string, unknown>;
  return (
    typeof record.id === 'string' &&
    (record.from === 'customer' || record.from === 'provider') &&
    typeof record.text === 'string' &&
    typeof record.at === 'string'
  );
};

const readThreads = (): ChatThread[] => {
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed: unknown = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === 'object')
      .map((item): ChatThread => ({
        threadId: String(item.threadId ?? ''),
        type: item.type === 'designer' ? 'designer' : 'store',
        id: String(item.id ?? ''),
        name: String(item.name ?? ''),
        phone: String(item.phone ?? ''),
        messages: Array.isArray(item.messages) ? item.messages.filter(isMessage) : [],
        updatedAt: String(item.updatedAt ?? ''),
      }))
      .filter((thread) => thread.threadId && thread.id);
  } catch {
    return [];
  }
};

const writeThreads = (threads: ChatThread[]) => {
  if (typeof window === 'undefined') return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(threads));
  } catch {
    // التخزين غير متاح — تبقى المحادثات في الجلسة الحالية
  }
};

export const ChatProvider = ({ children }: { children: ReactNode }) => {
  const [threads, setThreads] = useState<ChatThread[]>(() => readThreads());
  const [activeId, setActiveId] = useState<string | null>(null);

  useEffect(() => {
    writeThreads(threads);
  }, [threads]);

  const openChat = useCallback((target: ChatTarget) => {
    const threadId = `${target.type}-${target.id}`;
    setThreads((current) => {
      if (current.some((thread) => thread.threadId === threadId)) return current;
      return [
        ...current,
        {
          ...target,
          threadId,
          messages: [],
          updatedAt: new Date().toISOString(),
        },
      ];
    });
    setActiveId(threadId);
  }, []);

  const closeChat = useCallback(() => setActiveId(null), []);

  const sendMessage = useCallback(
    (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || !activeId) return;
      const message: ChatMessage = {
        id: `m-${Date.now()}`,
        from: 'customer',
        text: trimmed,
        at: new Date().toISOString(),
      };
      setThreads((current) =>
        current.map((thread) =>
          thread.threadId === activeId
            ? {
                ...thread,
                messages: [...thread.messages, message],
                updatedAt: message.at,
              }
            : thread,
        ),
      );
    },
    [activeId],
  );

  const activeThread = useMemo(
    () => threads.find((thread) => thread.threadId === activeId) ?? null,
    [threads, activeId],
  );

  const totalMessages = useMemo(
    () => threads.reduce((total, thread) => total + thread.messages.length, 0),
    [threads],
  );

  const value = useMemo<ChatContextValue>(
    () => ({ threads, activeThread, openChat, closeChat, sendMessage, totalMessages }),
    [threads, activeThread, openChat, closeChat, sendMessage, totalMessages],
  );

  return <ChatContext.Provider value={value}>{children}</ChatContext.Provider>;
};

export const useChat = () => {
  const context = useContext(ChatContext);
  if (!context) throw new Error('useChat must be used inside ChatProvider');
  return context;
};

