              <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" strokeWidth={1.6} />
              <div>
                <p className="text-sm font-medium">العنوان</p>
                <p className="mt-1 text-sm text-muted-foreground">المكلا — حضرموت، اليمن</p>
