import { useMemo, useRef, useState } from 'react';
import { ArrowLeft, ImagePlus, Loader2, Sparkles, Upload, Wand2 } from 'lucide-react';
import { Link } from 'react-router-dom';
import PageMeta from '@/components/common/PageMeta';
import { Button } from '@/components/ui/button';
import { useCatalog } from '@/contexts/CatalogContext';
import { formatPrice, IMG } from '@/data/catalog';
import { cn } from '@/lib/utils';

const rooms = [
  { id: 'living', label: 'غرفة معيشة', image: IMG.showroomLiving, keyword: 'معيشة' },
  { id: 'bedroom', label: 'غرفة نوم', image: IMG.showroomBedroom, keyword: 'نوم' },
  { id: 'majlis', label: 'مجلس', image: IMG.showroomMajlis, keyword: 'مجلس' },
  { id: 'dining', label: 'غرفة طعام', image: IMG.showroomDining, keyword: 'طعام' },
] as const;

const styles = [
  { id: 'warm', label: 'دافئ خشبي', hex: '#8C6D53', tint: 'rgba(140,109,83,0.18)' },
  { id: 'cream', label: 'كريمي ناعم', hex: '#DED6C8', tint: 'rgba(222,214,200,0.28)' },
  { id: 'sand', label: 'رملي هادئ', hex: '#A68966', tint: 'rgba(166,137,102,0.2)' },
  { id: 'espresso', label: 'إسبريسو فاخر', hex: '#231F1E', tint: 'rgba(35,31,30,0.16)' },
] as const;

const DesignerPage = () => {
  const { products } = useCatalog();
  const [room, setRoom] = useState<(typeof rooms)[number]['id']>('living');
  const [style, setStyle] = useState<(typeof styles)[number]['id']>('warm');
  const [photo, setPhoto] = useState<string | null>(null);
  const [dragging, setDragging] = useState(false);
  const [phase, setPhase] = useState<'idle' | 'analyzing' | 'done'>('idle');
  const [split, setSplit] = useState(55);
  const inputRef = useRef<HTMLInputElement>(null);

  const activeRoom = rooms.find((item) => item.id === room) ?? rooms[0];
  const activeStyle = styles.find((item) => item.id === style) ?? styles[0];

  const matches = useMemo(() => {
    const filtered = products.filter((product) => product.category.includes(activeRoom.keyword));
    return (filtered.length > 0 ? filtered : products).slice(0, 3);
  }, [products, activeRoom.keyword]);

  const handleFile = (file: File | undefined) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setPhoto(String(reader.result));
    reader.readAsDataURL(file);
  };

  const generate = () => {
    setPhase('analyzing');
    window.setTimeout(() => setPhase('done'), 2000);
  };

  return (
    <>
      <PageMeta
        title="مصمم الذكاء الاصطناعي — إيوان"
        description="اختر نوع الغرفة والطابع اللوني وارفع صورة مساحتك، واحصل على تصور تصميم داخلي مع القطع المطابقة من معارض المكلا."
      />
      <div className="mx-auto w-full max-w-7xl px-6 pb-16 md:pb-24">
        <div className="border-b border-border py-8 md:py-12">
          <p className="eyebrow">مصمم الذكاء الاصطناعي</p>
          <h1 className="mt-3 max-w-2xl font-display text-3xl leading-tight text-balance md:text-5xl">
            تخيّل مساحتك قبل أن تشتري
          </h1>
          <p className="mt-4 max-w-xl text-pretty text-sm leading-relaxed text-muted-foreground md:text-base">
            اختر نوع الغرفة والطابع اللوني، وارفع صورة مساحتك — وسنعرض لك تصوراً للتصميم مع القطع
            المطابقة من معارض إيوان.
          </p>
        </div>

        <div className="mt-8 grid gap-8 md:grid-cols-[1fr_1.1fr] md:gap-12">
          <div className="space-y-7">
            <div>
              <p className="text-sm font-medium">١. نوع الغرفة</p>
              <div className="mt-3 grid grid-cols-2 gap-3">
                {rooms.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => {
                      setRoom(item.id);
                      setPhase('idle');
                    }}
                    className={cn(
                      'group overflow-hidden rounded-2xl border text-right transition-colors',
                      room === item.id ? 'border-wood' : 'border-border hover:border-wood/40',
                    )}
                  >
                    <div className="aspect-[4/3] w-full overflow-hidden bg-muted">
                      <img
                        src={item.image}
                        alt={item.label}
                        loading="lazy"
                        className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105"
                      />
                    </div>
                    <p className="px-3 py-2 text-xs font-medium">{item.label}</p>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <p className="text-sm font-medium">٢. الطابع اللوني</p>
              <div className="mt-3 grid grid-cols-2 gap-2">
                {styles.map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => {
                      setStyle(item.id);
                      setPhase('idle');
                    }}
                    className={cn(
                      'flex items-center gap-2 rounded-full border px-3 py-2 text-xs transition-colors',
                      style === item.id
                        ? 'border-wood bg-sand/40'
                        : 'border-border hover:border-wood/40',
                    )}
                  >
                    <span
                      className="h-4 w-4 shrink-0 rounded-full border border-border"
                      style={{ backgroundColor: item.hex }}
                    />
                    {item.label}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <p className="text-sm font-medium">٣. صورة مساحتك (اختياري)</p>
              <div
                onDragOver={(event) => {
                  event.preventDefault();
                  setDragging(true);
                }}
                onDragLeave={() => setDragging(false)}
                onDrop={(event) => {
                  event.preventDefault();
                  setDragging(false);
                  handleFile(event.dataTransfer.files?.[0]);
                }}
                className={cn(
                  'mt-3 flex flex-col items-center justify-center rounded-2xl border border-dashed px-4 py-7 text-center transition-colors',
                  dragging ? 'border-wood bg-sand/40' : 'border-border bg-card',
                )}
              >
                {photo ? (
                  <img
                    src={photo}
                    alt="صورة المساحة المرفوعة"
                    className="h-24 w-full rounded-xl object-cover"
                  />
                ) : (
                  <>
                    <Upload className="h-5 w-5 text-wood" strokeWidth={1.5} />
                    <p className="mt-2 text-xs text-muted-foreground">
                      اسحب الصورة هنا أو ارفعها من جهازك
                    </p>
                  </>
                )}
                <input
                  ref={inputRef}
                  type="file"
                  accept="image/*"
                  className="hidden"
                  onChange={(event) => {
                    handleFile(event.target.files?.[0]);
                    event.target.value = '';
                  }}
                />
                <Button
                  type="button"
                  variant="outline"
                  onClick={() => inputRef.current?.click()}
                  className="mt-3 h-9 rounded-full border-border px-4 text-xs hover:border-wood/60"
                >
                  <ImagePlus className="ml-1.5 h-3.5 w-3.5" strokeWidth={1.6} />
                  اختيار صورة
                </Button>
              </div>
            </div>

            <Button
              onClick={generate}
              disabled={phase === 'analyzing'}
              className="h-12 w-full rounded-full bg-primary text-primary-foreground hover:bg-primary/90"
            >
              {phase === 'analyzing' ? (
                <Loader2 className="ml-2 h-4 w-4 animate-spin" strokeWidth={1.8} />
              ) : (
                <Wand2 className="ml-2 h-4 w-4" strokeWidth={1.7} />
              )}
              {phase === 'analyzing' ? 'جارٍ تحليل المساحة…' : 'توليد التصميم بالذكاء الاصطناعي'}
            </Button>
          </div>

          <div>
            <div className="overflow-hidden rounded-3xl border border-border bg-card">
              <div className="relative aspect-[4/3] w-full overflow-hidden bg-muted">
                <img
                  src={photo ?? activeRoom.image}
                  alt="قبل التصميم"
                  className="absolute inset-0 h-full w-full object-cover"
                  style={{ filter: 'grayscale(0.55) brightness(0.96)' }}
                />
                <div
                  className="absolute inset-0 overflow-hidden"
                  style={{ clipPath: `inset(0 0 0 ${split}%)` }}
                >
                  <img
                    src={activeRoom.image}
                    alt="بعد التصميم"
                    className="h-full w-full object-cover"
                  />
                  <span
                    aria-hidden
                    className="absolute inset-0"
                    style={{ backgroundColor: activeStyle.tint }}
                  />
                </div>

                <span className="absolute right-3 top-3 rounded-full bg-background/90 px-3 py-1 text-[11px] backdrop-blur">
                  {activeRoom.label} · {activeStyle.label}
                </span>

                {phase === 'analyzing' && (
                  <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-background/85 backdrop-blur">
                    <Loader2 className="h-6 w-6 animate-spin text-wood" strokeWidth={1.6} />
                    <p className="text-xs text-muted-foreground">
                      نحلّل الأبعاد والإضاءة ونطابق الطابع اللوني…
                    </p>
                  </div>
                )}
              </div>

              <div className="space-y-3 p-4">
                <div className="flex items-center justify-between text-[11px] text-muted-foreground">
                  <span>قبل</span>
                  <span>بعد</span>
                </div>
                <input
                  type="range"
                  min={0}
                  max={100}
                  value={split}
                  onChange={(event) => setSplit(Number(event.target.value))}
                  aria-label="مقارنة قبل وبعد"
                  className="w-full accent-[hsl(var(--wood))]"
                />
                <p className="text-pretty text-[11px] leading-relaxed text-muted-foreground">
                  اسحب المؤشر لمقارنة مساحتك الحالية بالتصور المقترح. التصور استرشادي ويمكن تنفيذه
                  عبر ورش النجارة المعتمدة في إيوان.
                </p>
              </div>
            </div>

            {phase === 'done' && (
              <div className="mt-6">
                <div className="flex items-center gap-2">
                  <Sparkles className="h-4 w-4 text-wood" strokeWidth={1.6} />
                  <p className="text-sm font-medium">القطع المطابقة لهذا التصور</p>
                </div>
                <ul className="mt-3 space-y-2">
                  {matches.map((product) => (
                    <li
                      key={product.dbId || product.id}
                      className="flex items-center gap-3 rounded-2xl border border-border bg-card p-2.5"
                    >
                      <div className="h-14 w-14 shrink-0 overflow-hidden rounded-xl bg-muted">
                        <img
                          src={product.images?.[0] ?? ''}
                          alt={product.name}
                          className="h-full w-full object-cover"
                        />
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-xs font-medium">{product.name}</p>
                        <p className="mt-0.5 text-[11px] text-muted-foreground">
                          {formatPrice(product.price)}
                        </p>
                      </div>
                      <Link
                        to={`/product/${product.slug}`}
                        className="flex shrink-0 items-center gap-1 rounded-full border border-wood/40 px-3 py-1.5 text-[11px] text-wood transition-colors hover:bg-sand/40"
                      >
                        اطلب
                        <ArrowLeft className="h-3 w-3" strokeWidth={1.8} />
                      </Link>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
};

export default DesignerPage;

