import { useCatalog } from '@/contexts/CatalogContext';
import { lookbook, lookbookPieces } from '@/data/catalog';

const LookbookPage = () => {
  const [active, setActive] = useState<(typeof lookbook)[number] | null>(null);
  const { products, stores } = useCatalog();

  return (
    <>
      <PageMeta
        title="كتالوج الإلهام — إيوان"
        description="مساحات ملهمة من بيوت حضرموت بأثاث من معارض المكلا."
      />
      <div className="mx-auto w-full max-w-[1440px] px-4 pb-16 md:px-8 md:pb-24">
        <div className="border-b border-border py-10 md:py-14">
          <p className="eyebrow">كتالوج الإلهام</p>
          <h1 className="mt-3 max-w-2xl font-display text-3xl leading-tight text-balance md:text-5xl">
            مساحات حقيقية من بيوت حضرموت
          </h1>
          <p className="mt-4 max-w-xl text-pretty text-sm leading-relaxed text-muted-foreground md:text-base">
            تصفّح مساحات منفّذة بأثاث معارض المكلا، واستلهم التوزيع والألوان قبل أن تبدأ.
          </p>
        </div>

        <div className="mt-8 grid grid-cols-2 gap-3 md:grid-cols-3 md:gap-5">
          {lookbook.map((item, index) => (
            <button
              key={item.id}
              type="button"
              onClick={() => setActive(item)}
              className={
                index % 5 === 0
                  ? 'group relative col-span-2 overflow-hidden rounded-2xl bg-muted text-right'
                  : 'group relative overflow-hidden rounded-2xl bg-muted text-right'
              }
            >
              <div className={index % 5 === 0 ? 'aspect-[16/10] w-full' : 'aspect-[4/5] w-full'}>
                <img
                  src={item.image}
                  alt={item.title}
                  loading="lazy"
                  className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-105"
                />
              </div>
              <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/60 to-transparent p-4">
                <p className="text-sm font-medium text-white">{item.title}</p>
                <p className="mt-0.5 text-xs text-white/75">{item.area}</p>
              </div>
            </button>
          ))}
        </div>
      </div>

      <Dialog open={Boolean(active)} onOpenChange={(open) => !open && setActive(null)}>
        <DialogContent className="max-h-[90dvh] max-w-[calc(100%-2rem)] overflow-y-auto rounded-3xl border-border bg-background p-0 sm:rounded-3xl md:max-w-2xl">
          {active && (
            <>
              <div className="aspect-[16/10] w-full overflow-hidden rounded-t-3xl bg-muted">
                <img src={active.image} alt={active.title} className="h-full w-full object-cover" />
              </div>
              <div className="p-6">
                <DialogHeader>
                  <DialogTitle className="font-display text-xl text-balance">{active.title}</DialogTitle>
                  <DialogDescription className="text-pretty text-sm text-muted-foreground">
                    {active.area} · {active.style}
                  </DialogDescription>
                </DialogHeader>
                <p className="mt-4 text-pretty text-sm leading-relaxed text-muted-foreground">
                  {active.description}
                </p>

                <div className="mt-6 border-t border-border pt-5">
                  <p className="text-sm font-medium">القطع والمتاجر المنفذة لهذا الإلهام</p>
                  <ul className="mt-3 space-y-2">
                    {(lookbookPieces[active.id] ?? []).map((piece) => {
                      const product = products.find((item) => item.id === piece.productId);
                      const store = stores.find((item) => item.id === piece.storeId);
                      if (!product) return null;
                      return (
                        <li
                          key={`${active.id}-${piece.productId}`}
                          className="flex items-center justify-between gap-3 rounded-xl border border-border bg-card px-3 py-2.5"
                        >
                          <div className="min-w-0">
                            <p className="truncate text-xs font-medium">{product.name}</p>
                            <p className="mt-0.5 text-[11px] text-wood">{store?.name ?? 'معرض إيوان'}</p>
                          </div>
                          <Link
                            to={`/product/${product.slug}`}
                            className="flex shrink-0 items-center gap-1 rounded-full border border-wood/40 px-3 py-1.5 text-[11px] text-wood transition-colors hover:bg-sand/40"
                          >
                            اطلب القطعة
                            <ArrowLeft className="h-3 w-3" strokeWidth={1.8} />
                          </Link>
                        </li>
                      );
                    })}
                  </ul>
                </div>
              </div>
            </>
          )}
        </DialogContent>
      </Dialog>
    </>
  );
};

export default LookbookPage;

