import { useMemo, useState } from 'react';
import {
  ArrowLeft,
  BadgeCheck,
  Heart,
  MapPin,
  MessageCircle,
  Minus,
  Plus,
  ShieldCheck,
  ShoppingBag,
  Truck,
} from 'lucide-react';
import { Link, useParams } from 'react-router-dom';
import PageMeta from '@/components/common/PageMeta';
import { ProductCard } from '@/components/product/ProductCard';
import { StarRating } from '@/components/product/StarRating';
import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useAuth } from '@/contexts/AuthContext';
import { useCatalog } from '@/contexts/CatalogContext';
import { useChat } from '@/contexts/ChatContext';
import { useStore } from '@/contexts/StoreContext';
import { formatPrice } from '@/data/catalog';
import {
  buildOrderMessage,
  productCode,
  serializeOrderDetails,
  waLink,
} from '@/lib/order';
import { cn } from '@/lib/utils';

const ProductPage = () => {
  const { slug } = useParams();
  const { products, stores, createRequest } = useCatalog();
  const { addToCart, toggleWishlist, isWishlisted } = useStore();
  const { openChat } = useChat();
  const { profile } = useAuth();
  const [quantity, setQuantity] = useState(1);
  const [colorIndex, setColorIndex] = useState(0);
  const [orderOpen, setOrderOpen] = useState(false);
  const [customerName, setCustomerName] = useState(profile?.fullName ?? '');
  const [customerPhone, setCustomerPhone] = useState(profile?.phone ?? '');
  const [submitting, setSubmitting] = useState(false);

  const product = products.find((item) => item.slug === slug);
  const store = stores.find((item) => item.id === product?.storeId);
  const related = useMemo(
    () =>
      products
        .filter((item) => item.id !== product?.id && item.category === product?.category)
        .slice(0, 4),
    [products, product],
  );

  if (!product) {
    return (
      <div className="mx-auto w-full max-w-7xl px-6 py-24 text-center">
        <h1 className="font-display text-3xl">لم نجد هذه القطعة</h1>
        <p className="mt-3 text-sm text-muted-foreground">ربما تم حذفها أو تغيّر رابطها.</p>
        <Button asChild className="mt-6 h-11 rounded-full bg-primary px-6 text-primary-foreground">
          <Link to="/shop">العودة إلى المتجر</Link>
        </Button>
      </div>
    );
  }

  const saved = isWishlisted(product.id);
  const colors = product.colors ?? [];
  const images = product.images ?? [];
  const color = colors[colorIndex]?.name ?? 'افتراضي';
  const activeImage = images[colorIndex] ?? images[0] ?? '';
  const hasAlternateImage = images.length > 1 && Boolean(images[colorIndex]);
  const code = productCode(product.id);

  const status = !product.available
    ? { label: 'نفذت الكمية', className: 'bg-sand text-sand-foreground' }
    : product.badge?.includes('جديد')
      ? { label: 'جديد', className: 'bg-wood text-primary-foreground' }
      : { label: 'متوفر', className: 'bg-primary text-primary-foreground' };

  const handleOrder = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!product.available) return;
    setSubmitting(true);
    const storeName = store?.name ?? 'إيوان';
    const message = buildOrderMessage({
      storeName,
      productName: product.name,
      quantity,
      code,
    });

    await createRequest({
      type: 'order',
      name: customerName || 'عميل إيوان',
      phone: customerPhone,
      details: serializeOrderDetails({
        kind: 'order',
        productName: product.name,
        productCode: code,
        quantity,
        storeName,
        price: product.price * quantity,
        customerName: customerName || 'عميل إيوان',
        phone: customerPhone,
        date: new Date().toISOString(),
      }),
      status: 'new',
    }).catch(() => undefined);

    setSubmitting(false);
    setOrderOpen(false);
    if (store?.phone) {
      window.open(waLink(store.phone, message), '_blank', 'noopener');
    }
  };

  return (
    <>
      <PageMeta title={`${product.name} — إيوان`} description={product.description} />
      <div className="mx-auto w-full max-w-7xl px-6 pb-16 md:pb-24">
        <nav className="flex items-center gap-2 py-5 text-xs text-muted-foreground">
          <Link to="/" className="hover:text-foreground">الرئيسية</Link>
          <span>/</span>
          <Link to="/shop" className="hover:text-foreground">المتجر</Link>
          <span>/</span>
          <span className="truncate text-foreground">{product.name}</span>
        </nav>

        <div className="grid gap-8 md:grid-cols-2 md:gap-14">
          <div className="space-y-3">
            <div className="relative aspect-[4/5] w-full overflow-hidden rounded-3xl bg-muted">
              <img src={activeImage} alt={product.name} className="h-full w-full object-cover" />
              {colors[colorIndex] && !hasAlternateImage && (
                <span
                  aria-hidden
                  className="pointer-events-none absolute inset-0 transition-colors duration-500"
                  style={{
                    backgroundColor: colors[colorIndex].hex,
                    opacity: 0.14,
                    mixBlendMode: 'multiply',
                  }}
                />
              )}
              <span
                className={cn(
                  'absolute right-4 top-4 rounded-full px-3 py-1 text-[11px] font-medium',
                  status.className,
                )}
              >
                {status.label}
              </span>
            </div>
            {images.length > 1 && (
              <div className="grid grid-cols-4 gap-3">
                {images.slice(0, 4).map((image, index) => (
                  <button
                    key={index}
                    type="button"
                    onClick={() => setColorIndex(index)}
                    className={cn(
                      'aspect-square overflow-hidden rounded-xl border bg-muted transition-colors',
                      colorIndex === index ? 'border-wood' : 'border-transparent',
                    )}
                  >
                    <img src={image} alt="" className="h-full w-full object-cover" loading="lazy" />
                  </button>
                ))}
              </div>
            )}
          </div>

          <div>
            <div className="flex flex-wrap items-center gap-2">
              <span className="inline-flex rounded-full bg-secondary px-3 py-1 text-[11px]">
                {product.category}
              </span>
              <span className="inline-flex rounded-full border border-border px-3 py-1 text-[11px] text-muted-foreground">
                رقم القطعة: {code}
              </span>
            </div>
            <h1 className="mt-3 font-display text-2xl leading-tight text-balance md:text-4xl">
              {product.name}
            </h1>

            <div className="mt-3 flex flex-wrap items-center gap-4">
              <StarRating rating={product.rating} reviews={product.reviews} />
            </div>

