                توصيل وتركيب داخل المكلا
              </div>
              <div className="flex items-center gap-2 rounded-2xl bg-secondary px-4 py-3 text-xs text-muted-foreground">
                <ShieldCheck className="h-4 w-4 shrink-0 text-wood" strokeWidth={1.6} />
